 "Qualifikationsverfahren. ABU-Schlussprüfung: 70 min «Gesellschaft» + 70 min «Sprache & Kommunikation». Hilfsmittel: Duden, Gesetzestexte (ZGB/OR/BV), Taschenrechner.": "Procédure de qualification. Examen final ABU : 70 min « Société » + 70 min « Langue & communication ». Outils : Duden, textes légaux (ZGB/OR/BV), calculatrice.",
